{
  "name": "Zaber电动位移台",
  "name_en": "Zaber motorized stage",
  "manufacturer": "Zaber Technologies",
  "description": "这是一类通过串口 ASCII 协议控制的精密电动位移设备，通常具有一个或多个运动轴，可执行回零、绝对位移、相对位移和连续运动。它常用于实验室中的样品、光学元件、探针或夹具的精密定位与自动化扫描。",
  "description_en": "This is a precision motorized positioning device controlled over a serial ASCII protocol, typically with one or more motion axes for homing, absolute moves, relative moves, and continuous motion. It is commonly used in laboratories for precise positioning and automated scanning of samples, optical components, probes, or fixtures.",
  "tag_hints": [
    "motorized positioning",
    "translation stage",
    "multi-axis motion control",
    "serial ASCII protocol",
    "precision alignment",
    "laboratory automation"
  ],
  "actions": [
    {
      "action_name": "auto-write",
      "description": "向设备串口写入一条 ASCII 命令。",
      "description_en": "Write an ASCII command to the device serial port."
    },
    {
      "action_name": "auto-read",
      "description": "从设备串口读取一条 ASCII 回复。",
      "description_en": "Read an ASCII reply from the device serial port."
    },
    {
      "action_name": "auto-flush",
      "description": "清空串口通信缓冲区。",
      "description_en": "Flush the serial communication buffers."
    },
    {
      "action_name": "auto-open",
      "description": "打开与设备的串口连接。",
      "description_en": "Open the serial connection to the device."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与设备的串口连接。",
      "description_en": "Close the serial connection to the device."
    },
    {
      "action_name": "auto-timeout",
      "description": "获取/设置通信超时时间。",
      "description_en": "Get/set communication timeout."
    },
    {
      "action_name": "auto-baudrate",
      "description": "获取/设置串口波特率。",
      "description_en": "Get/set serial baud rate."
    },
    {
      "action_name": "auto-send",
      "description": "发送一条 ASCII 命令并接收设备回复。",
      "description_en": "Send an ASCII command and receive the device reply."
    },
    {
      "action_name": "auto-home",
      "description": "使运动轴执行回零/归位。",
      "description_en": "Home the motion axis."
    },
    {
      "action_name": "auto-move_abs",
      "description": "将运动轴移动到绝对位置。",
      "description_en": "Move the motion axis to an absolute position."
    },
    {
      "action_name": "auto-move_rel",
      "description": "使运动轴相对当前位置移动指定距离。",
      "description_en": "Move the motion axis by a relative distance."
    },
    {
      "action_name": "auto-move_vel",
      "description": "使运动轴按指定速度连续运动。",
      "description_en": "Move the motion axis continuously at a specified velocity."
    },
    {
      "action_name": "auto-get_status",
      "description": "获取设备或运动轴的状态。",
      "description_en": "Get the status of the device or motion axis."
    },
    {
      "action_name": "auto-poll_until_idle",
      "description": "轮询设备状态直到空闲。",
      "description_en": "Poll the device status until it becomes idle."
    },
    {
      "action_name": "auto-encode",
      "description": "将命令编码为 Zaber ASCII 协议消息。",
      "description_en": "Encode a command into a Zaber ASCII protocol message."
    },
    {
      "action_name": "auto-axis",
      "description": "选择指定编号的运动轴。",
      "description_en": "Select a motion axis by its number."
    }
  ]
}

